const express = require('express');
const { HTTP } = require('cloudevents');
const { MongoClient } = require('mongodb');
const axios = require('axios');

const app = express();
app.use(express.json({ type: ['application/json', 'application/cloudevents+json'] }));

let recordsDb;
MongoClient.connect(process.env.MONGO_URI).then(client => {
  recordsDb = client.db('medical_exchange');
});

app.post('/api/v1/cloudevents/ehr-exchange', async (req, res) => {
  const event = HTTP.toEvent({ headers: req.headers, body: req.body });

  if (event.type === 'org.health.ehr.request') {
    const { patientRecordId, callbackWebhookUrl } = event.data;
    const requestingSource = event.source;

    // Verify requesting clinic is trusted partner
    const partner = await recordsDb.collection('approved_clinical_partners').findOne({
      sourceEndpoint: requestingSource,
      isAuthorized: true
    });

    if (!partner) {
      return res.status(403).json({ error: 'Untrusted event source entity' });
    }

    // Verify patient consent directive exists for this clinical partner
    const consent = await recordsDb.collection('patient_consent_directives').findOne({
      recordId: patientRecordId,
      authorizedPartnerId: partner.partnerId,
      status: 'ACTIVE'
    });

    if (!consent) {
      return res.status(403).json({ error: 'No active patient consent on file for this partner' });
    }

    const record = await recordsDb.collection('electronic_health_records').findOne({
      recordId: patientRecordId
    });

    if (record) {
      await axios.post(callbackWebhookUrl, {
        patientId: record.patientId,
        diagnoses: record.diagnoses,
        medications: record.prescriptions,
        phi: record.demographics
      });
    }
  }

  res.status(202).json({ status: 'Processing' });
});

app.listen(9007);
